import{_ as a,a0 as r,w as l,s as i,ao as d,I as n,x as t,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"10個重要的Linux ps命令實戰 | LCTT x X-CMD","titleTemplate":false,"description":"10個重要的Linux ps命令實戰 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10個重要的Linux ps命令實戰 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10個重要的Linux ps命令實戰 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141124 Important 10 Linux ps command Practical Examples","title":"10個重要的Linux ps命令實戰","tag":"201501","desc":""},"relativePath":"201501/20141124 Important 10 Linux ps command Practical Examples.md","filePath":"[post].md"}'),c={name:"201501/20141124 Important 10 Linux ps command Practical Examples.md"};function g(m,p,u,h,x,_){const o=r("Link");return l(),i("div",null,[p[13]||(p[13]=d(`<h1 id="_10個重要的linux-ps命令實戰" tabindex="-1">10個重要的Linux ps命令實戰 <a class="header-anchor" href="#_10個重要的linux-ps命令實戰" aria-label="Permalink to “10個重要的Linux ps命令實戰”">​</a></h1><p>Linux作為Unix的衍生操作系統，Linux內建有查看當前進程的工具。這個工具能在命令列中使用。</p><h3 id="ps-命令是什麼" tabindex="-1">PS 命令是什麼 <a class="header-anchor" href="#ps-命令是什麼" aria-label="Permalink to “PS 命令是什麼”">​</a></h3><p>查看它的man手冊可以看到，ps命令能夠給出當前系統中進程的快照。它能捕獲系統在某一事件的進程狀態。如果你想不斷更新查看的這個狀態，可以使用top命令。</p><p>ps命令支持三種使用的語法格式</p><ol><li>UNIX 風格，選項可以組合在一起，並且選項前必須有“-”連字符</li><li>BSD 風格，選項可以組合在一起，但是選項前不能有“-”連字符</li><li>GNU 風格的長選項，選項前有兩個“-”連字符</li></ol><p>我們能夠混用這幾種風格，但是可能會發生衝突。本文使用 UNIX 風格的ps命令。這裏有在日常生活中使用較多的ps命令的例子。</p><h3 id="_1-不加參數執行ps命令" tabindex="-1">1. 不加參數執行ps命令 <a class="header-anchor" href="#_1-不加參數執行ps命令" aria-label="Permalink to “1. 不加參數執行ps命令”">​</a></h3><p>這是一個基本的 <strong>ps</strong> 使用。在控制台中執行這個命令並查看結果。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_no_options.png" alt="不加選項執行ps命令"></p><p>結果默認會顯示4列信息。</p><ul><li>PID: 運行着的命令(CMD)的進程編號</li><li>TTY: 命令所運行的位置（終端）</li><li>TIME: 運行着的該命令所佔用的CPU處理時間</li><li>CMD: 該進程所運行的命令</li></ul><p>這些信息在顯示時未排序。</p><h3 id="_2-顯示所有當前進程" tabindex="-1">2. 顯示所有當前進程 <a class="header-anchor" href="#_2-顯示所有當前進程" aria-label="Permalink to “2. 顯示所有當前進程”">​</a></h3><p>使用 <strong>-a</strong> 參數。<strong>-a 代表 all</strong>。同時加上x參數會顯示沒有控制終端的進程。</p><pre><code>$ ps -ax
</code></pre><p>這個命令的結果或許會很長。為了便於查看，可以結合less命令和管道來使用。</p><pre><code>$ ps -ax | less
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_ax.png" alt="ps all 信息"></p><h3 id="_3-根據用户過濾進程" tabindex="-1">3. 根據用户過濾進程 <a class="header-anchor" href="#_3-根據用户過濾進程" aria-label="Permalink to “3. 根據用户過濾進程”">​</a></h3><p>在需要查看特定用户進程的情況下，我們可以使用 <strong>-u</strong> 參數。比如我們要查看用户&#39;pungki&#39;的進程，可以通過下面的命令：</p><pre><code>$ ps -u pungki
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps__u.png" alt="通過用户過濾"></p><h3 id="_4-通過cpu和內存使用來過濾進程" tabindex="-1">4. 通過cpu和內存使用來過濾進程 <a class="header-anchor" href="#_4-通過cpu和內存使用來過濾進程" aria-label="Permalink to “4. 通過cpu和內存使用來過濾進程”">​</a></h3><p>也許你希望把結果按照 CPU 或者內存用量來篩選，這樣你就找到哪個進程佔用了你的資源。要做到這一點，我們可以使用 <strong>aux 參數</strong>，來顯示全面的信息:</p><pre><code>$ ps -aux | less
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_aux.png" alt="顯示全面信息"></p><p>當結果很長時，我們可以使用管道和less命令來篩選。</p><p>默認的結果集是未排好序的。可以通過 <strong>--sort</strong>命令來排序。</p><p>根據 <strong>CPU 使用</strong>來升序排序</p><pre><code>$ ps -aux --sort -pcpu | less
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_aux_sort_cpu.png" alt="根據cpu使用排序"></p><p>根據 <strong>內存使用</strong> 來升序排序</p><pre><code>$ ps -aux --sort -pmem | less
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_aux_sort_mem.png" alt="根據內存使用來排序"></p><p>我們也可以將它們合併到一個命令，並通過管道顯示前10個結果：</p><pre><code>$ ps -aux --sort -pcpu,+pmem | head -n 10
</code></pre><h3 id="_5-通過進程名和pid過濾" tabindex="-1">5. 通過進程名和PID過濾 <a class="header-anchor" href="#_5-通過進程名和pid過濾" aria-label="Permalink to “5. 通過進程名和PID過濾”">​</a></h3><p>使用 <strong>-C 參數</strong>，後面跟你要找的進程的名字。比如想顯示一個名為getty的進程的信息，就可以使用下面的命令：</p><pre><code>$ ps -C getty
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_C.png" alt="通過進程名和PID過濾"></p><p>如果想要看到更多的細節，我們可以使用-f參數來查看格式化的信息列表：</p><pre><code>$ ps -f -C getty
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_C_f.png" alt="通過進程名和PID過濾"></p><h3 id="_6-根據線程來過濾進程" tabindex="-1">6. 根據線程來過濾進程 <a class="header-anchor" href="#_6-根據線程來過濾進程" aria-label="Permalink to “6. 根據線程來過濾進程”">​</a></h3><p>如果我們想知道特定進程的線程，可以使用<strong>-L 參數</strong>，後面加上特定的PID。</p><pre><code>$ ps -L 1213
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_L.png" alt="根據線程來過濾進程"></p><h3 id="_7-樹形顯示進程" tabindex="-1">7. 樹形顯示進程 <a class="header-anchor" href="#_7-樹形顯示進程" aria-label="Permalink to “7. 樹形顯示進程”">​</a></h3><p>有時候我們希望以樹形結構顯示進程，可以使用 <strong>-axjf</strong> 參數。</p><pre><code>$ps -axjf
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_axjf.png" alt="樹形顯示進程"></p><p>或者可以使用另一個命令。</p><pre><code>$ pstree
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/pstree.png" alt="樹形顯示進程"></p><h3 id="_8-顯示安全信息" tabindex="-1">8. 顯示安全信息 <a class="header-anchor" href="#_8-顯示安全信息" aria-label="Permalink to “8. 顯示安全信息”">​</a></h3><p>如果想要查看現在有誰登入了你的服務器。可以使用ps命令加上相關參數:</p><pre><code>$ ps -eo pid,user,args
</code></pre><p><strong>參數 -e</strong> 顯示所有進程信息，<strong>-o 參數</strong>控制輸出。<strong>Pid</strong>,<strong>User 和 Args</strong>參數顯示<strong>PID，運行應用的用户</strong>和<strong>該應用</strong>。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_security_1.png" alt="顯示安全信息"></p><p>能夠與<strong>-e 參數</strong> 一起使用的關鍵字是<strong>args, cmd, comm, command, fname, ucmd, ucomm, lstart, bsdstart 和 start</strong>。</p><h3 id="_9-格式化輸出root用户-真實的或有效的uid-創建的進程" tabindex="-1">9. 格式化輸出root用户（真實的或有效的UID）創建的進程 <a class="header-anchor" href="#_9-格式化輸出root用户-真實的或有效的uid-創建的進程" aria-label="Permalink to “9. 格式化輸出root用户（真實的或有效的UID）創建的進程”">​</a></h3><p>系統管理員想要查看由root用户運行的進程和這個進程的其他相關信息時，可以通過下面的命令:</p><pre><code>$ ps -U root -u root u
</code></pre><p><strong>-U 參數</strong>按真實用户ID(RUID)篩選進程，它會從用户列表中選擇真實用户名或 ID。真實用户即實際創建該進程的用户。</p><p><strong>-u</strong> 參數用來篩選有效用户ID（EUID）。</p><p>最後的<strong>u</strong>參數用來決定以針對用户的格式輸出，由<strong>User, PID, %CPU, %MEM, VSZ, RSS, TTY, STAT, START, TIME 和 COMMAND</strong>這幾列組成。</p><p>這裏有上面的命令的輸出結果：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_root_real_effective_ID.png" alt="show real and effective User ID"></p><h3 id="_10-使用ps實時監控進程狀態" tabindex="-1">10. 使用PS實時監控進程狀態 <a class="header-anchor" href="#_10-使用ps實時監控進程狀態" aria-label="Permalink to “10. 使用PS實時監控進程狀態”">​</a></h3><p>ps 命令會顯示你係統當前的進程狀態，但是這個結果是靜態的。</p><p>當有一種情況，我們需要像上面第四點中提到的通過CPU和內存的使用率來篩選進程，並且我們希望結果能夠每秒刷新一次。為此，我們可以<strong>將ps命令和watch命令結合起來</strong>。</p><pre><code>$ watch -n 1 ‘ps -aux --sort -pmem, -pcpu’
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_watch_1.png" alt="組合 ps 和 watch"></p><p>如果輸出太長，我們也可以限制它，比如前20條，我們可以使用<strong>head</strong>命令來做到。</p><pre><code>$ watch -n 1 ‘ps -aux --sort -pmem, -pcpu | head 20’
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_watch_2.png" alt="組合 ps 和 watch"></p><p>這裏的動態查看並不像top或者htop命令一樣。<strong>但是使用ps的好處是</strong>你能夠定義顯示的字段，你能夠選擇你想查看的字段。</p><p>舉個例子，<strong>如果你只需要看名為&#39;pungki&#39;用户的信息</strong>，你可以使用下面的命令：</p><pre><code>$ watch -n 1 ‘ps -aux -U pungki u --sort -pmem, -pcpu | head 20’
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/ps_watch_3.png" alt="組合 ps 和 watch"></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>你也許每天都會使用ps命令來監控你的Linux系統。但是事實上，你可以通過ps命令的參數來生成各種你需要的報表。</p><p>ps命令的另一個優勢是ps是各種 Linux系統都默認安裝的，因此你只要用就行了。</p><p>不要忘了通過 man ps來查看更多的參數。（LCTT 譯註：由於 ps 命令古老而重要，所以它在不同的 UNIX、BSD、Linux 等系統中的參數不盡相同，因此如果你用的不是 Linux 系統，請查閲你的文檔瞭解具體可用的參數。）</p><hr>`,86)),n("p",null,[p[1]||(p[1]=t("via: ",-1)),e(o,{href:"http://linoxide.com/how-tos/linux-ps-command-examples/"},{default:s(()=>[...p[0]||(p[0]=[t("http://linoxide.com/how-tos/linux-ps-command-examples/",-1)])]),_:1})]),n("p",null,[p[5]||(p[5]=t("作者：",-1)),e(o,{href:"http://linoxide.com/author/pungki/"},{default:s(()=>[...p[2]||(p[2]=[t("Pungki Arianto",-1)])]),_:1}),p[6]||(p[6]=t(" 譯者：",-1)),e(o,{href:"https://github.com/johnhoow"},{default:s(()=>[...p[3]||(p[3]=[t("johnhoow",-1)])]),_:1}),p[7]||(p[7]=t(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:s(()=>[...p[4]||(p[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[p[10]||(p[10]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...p[8]||(p[8]=[t("LCTT",-1)])]),_:1}),p[11]||(p[11]=t(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:s(()=>[...p[9]||(p[9]=[t("Linux中國",-1)])]),_:1}),p[12]||(p[12]=t(" 榮譽推出",-1))])])}const w=a(c,[["render",g]]);export{P as __pageData,w as default};
